    options: [`Intervir, lembrando os revisores dos seus papéis e responsabilidades específicas (por exemplo, técnico foca em técnico, negócios em negócios) e direcionando a discussão para garantir cobertura adequada.`, `Permitir que o revisor de negócios continue, pois sua experiência é valiosa, e esperar que os outros revisores eventualmente contribuam.`, `Sugerir que o revisor técnico prepare um relatório separado para os defeitos técnicos após a reunião.`, `Encerrar a reunião e convidar apenas os revisores técnicos para uma nova sessão privada.`],
