    options: [`Copiar um checklist genérico da internet para testes de regressão.`, `Criar um checklist baseado nas alterações feitas na atualização e nos requisitos relacionados.`, `Revisitar as principais características do sistema existentes antes da atualização, listar as funcionalidades críticas e as áreas com histórico de defeitos.`, `Pedir à equipe de desenvolvimento para listar as funcionalidades que eles 'acham' que podem ter sido afetadas.`],
