    topic: `Estratégias de Teste`,
    level: "K2",
    question: `Uma equipe de desenvolvimento está usando integração contínua e entrega contínua. Qual estratégia de teste seria mais apropriada para garantir que o software seja liberado regularmente e com alta qualidade?`,
    options: [`Estratégia reativa, focada na correção de defeitos após o feedback do usuário.`, `Estratégia baseada em processo ou método, seguindo um ciclo de vida de teste bem definido.`, `Estratégia analítica ou baseada em risco, para focar nas áreas mais críticas em cada iteração.`, `Estratégia consultiva, onde os testes são terceirizados para um especialista externo.`],
    correctAnswer: 2,
    explanation: `Em CI/CD, a agilidade e a resposta rápida a riscos emergentes são cruciais. Uma estratégia analítica ou baseada em risco permite focar os esforços de teste nas áreas mais importantes e problemáticas, garantindo que as releases frequentes sejam de boa qualidade.`,
