    options: [`Regressão verifica se funcionalidades existentes ainda funcionam, enquanto progressão verifica novas funcionalidades.`, `Regressão é realizada apenas manualmente, enquanto progressão é sempre automatizada.`, `Regressão foca em performance, enquanto progressão foca em segurança.`, `Regressão é feita por desenvolvedores, enquanto progressão é feita por testadores.`],
    correctAnswer: 0,
    explanation: `O teste de regressão foca em garantir que mudanças não causaram efeitos colaterais indesejados em partes já existentes e testadas do sistema. O teste de progressão (funcional) foca em verificar se as novas funcionalidades implementadas estão funcionando conforme o esperado.`,
