    question: `Em um projeto Scrum, a equipe precisa garantir que cada 'sprint' não introduza regressões no que já foi desenvolvido. Além disso, eles querem que os testes sejam executados rapidamente para fornecer feedback imediato. Qual tipo de ferramenta ou abordagem de automação seria mais adequada para essa necessidade?`,
    options: [`Automação de testes de regressão em nível de API ou componente`, `Testes manuais exploratórios extensivos`, `Priorização de testes de desempenho sobre testes funcionais`, `Uso de ferramentas de gerenciamento de requisitos para cada funcionalidade nova`],
