    options: [`Defeitos serão detectados mais cedo no ciclo de desenvolvimento, reduzindo seu custo de correção`, `A equipe de desenvolvimento não precisará mais realizar testes unitários`, `Todos os tipos de testes, incluindo usabilidade, serão totalmente automatizados`, `O número de defeitos introduzidos no software será zero`],
